import React, { useState } from "react";
import axios from "axios";
import { useNavigate, Link } from "react-router-dom";

export default function Login() {
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");

  const navigate = useNavigate();

  const handleLogin = async () => {
    try {
      const res = await axios.post(
        "http://localhost:9000/api/auth/login",
        {
          email,
          password,
        }
      );

      localStorage.setItem(
        "token",
        res.data.token
      );

      alert("Login Successful");

      navigate("/dashboard");
        navigate("/dashboard");
    } catch (err) {
      alert("Login Failed");
    }
  };

  return (
    <div style={styles.container}>
      <h1>Login</h1>

      <input
        style={styles.input}
        type="email"
        placeholder="Enter Email"
        onChange={(e) =>
          setEmail(e.target.value)
        }
      />

      <input
        style={styles.input}
        type="password"
        placeholder="Enter Password"
        onChange={(e) =>
          setPassword(e.target.value)
        }
      />

      <button
        style={styles.button}
        onClick={handleLogin}
      >
        Login
      </button>

      <p>
        Don't have account?
        <Link to="/signup">
          Signup
        </Link>
      </p>
    </div>
  );
}

const styles = {
  container: {
    width: "350px",
    margin: "100px auto",
    padding: "30px",
    background: "white",
    borderRadius: "10px",
    boxShadow: "0px 0px 10px #ccc",
    textAlign: "center",
  },

  input: {
    width: "100%",
    padding: "10px",
    marginTop: "10px",
  },

  button: {
    width: "100%",
    padding: "10px",
    marginTop: "15px",
    background: "#4f46e5",
    color: "white",
    border: "none",
  },
};
